 }
 bool RenderCivicManagementOperating(VisualElement body,VisualElement actions) {
  switch(_page) {
   case "population_home":case "population":case "demographics":CivicOMPopulation(body,actions);return true;
   case "economy_home":case "resources":case "finance":case "ledger":case "economy":CivicOMEconomy(body,actions);return true;
   case "market":case "orders":CivicOMMarket(body,actions);return true;
   case "policies":CivicOMPolicies(body,actions);return true;
   case "construction":CivicOMConstruction(body,actions);return true;
   default:return false;
  }
 }
 void CivicOMLayout(VisualElement body,CivicOperatingManagementState state,out VisualElement list,out VisualElement inspector) {
  var layout=C.Row(body,"c-management-layout");layout.style.flexGrow=1;layout.style.minHeight=0;
  list=C.Column(layout,"c-management-list");list.style.flexGrow=1;list.style.flexBasis=0;list.style.minWidth=0;list.style.minHeight=0;
  var inspection=C.Column(layout,"c-management-inspector");inspection.style.width=Length.Percent(33);inspection.style.minHeight=0;
