 }
 ScrollView CivicOMScroll(VisualElement parent,CivicOperatingManagementState state,bool inspector=false) {
  var scroll=new ScrollView(ScrollViewMode.Vertical);scroll.AddToClassList("c-management-scroll");scroll.style.flexGrow=1;scroll.style.minHeight=0;scroll.verticalScrollerVisibility=ScrollerVisibility.AlwaysVisible;scroll.horizontalScrollerVisibility=ScrollerVisibility.Hidden;scroll.mouseWheelScrollSize=48;parent.Add(scroll);
  var saved=inspector?state.inspectionScroll:state.listScroll;
  // Restore after layout has computed the scroll range, otherwise UITK clamps a saved offset to zero.
  bool restored=false;scroll.RegisterCallback<GeometryChangedEvent>(e=>{if(restored)return;scroll.schedule.Execute(()=>{if(restored)return;scroll.scrollOffset=saved;restored=true;scroll.verticalScroller.valueChanged+=value=>{var offset=scroll.scrollOffset;offset.y=value;if(inspector)state.inspectionScroll=offset;else state.listScroll=offset;};});});return scroll;
 }
 void CivicOMToolbar(VisualElement parent,CivicOperatingManagementState state,string[] filters,Func<string,string> filterTitle,string[] sorts,Func<string,string> sortTitle) {
