 V CivicOMEconomyRows(string resource) {
  var rows=V.Arr();var m=S["metrics"];
  if(resource=="currency") {
   var receipts=m.Get("fiscal_sources",V.Arr());var expenses=m.Get("fiscal_ledger",V.Arr()).Where(x=>x.Get("kind","").Text=="expense").ToArray();
   foreach(var id in receipts.Select(x=>x.Get("source_id","").Text).Union(expenses.Select(x=>x.Get("source_id","").Text))){var own=receipts.Where(x=>x.Get("source_id","").Text==id);double tax=own.Where(x=>x.Get("aggregate","").Text=="tax").Sum(x=>x.Get("rate",0).Double),land=own.Where(x=>x.Get("aggregate","").Text=="land_rent").Sum(x=>x.Get("rate",0).Double),pollution=own.Where(x=>x.Get("aggregate","").Text=="pollution_fee").Sum(x=>x.Get("rate",0).Double),upkeep=expenses.Where(x=>x.Get("source_id","").Text==id).Sum(x=>x.Get("rate",0).Double);rows.Add(V.Map("id",id,"name",OperatingProjectIdentity(id),"a",tax,"b",land,"c",pollution,"d",upkeep,"net",tax+land+pollution-upkeep));}
   var remainder=m.Get("income",0).Double-receipts.Sum(x=>x.Get("rate",0).Double);rows.Add(V.Map("id","__municipal","name","市政及未归属经营收入","a",0,"b",0,"c",0,"d",0,"net",remainder));return rows;
  }
  if(resource=="energy") {
   var supply=m.Get("energy_sources",V.Map());var demand=m.Get("energy_requests",V.Map());var people=m.Get("population_energy",V.Map());
   foreach(var id in supply.Keys.Union(demand.Keys).Union(people.Keys.Select(gid=>S["groups"].Get(gid,V.Map()).Get("host","").Text)).Where(id=>id!="")){double resident=people.Pairs.Where(x=>S["groups"].Get(x.Key,V.Map()).Get("host","").Text==id).Sum(x=>x.Value.Double);rows.Add(V.Map("id",id,"name",id=="municipal"?"市政基础供电":OperatingProjectIdentity(id),"a",supply.Get(id,0).Double,"b",demand.Get(id,0).Double,"c",resident,"net",supply.Get(id,0).Double-demand.Get(id,0).Double-resident));}return rows;
  }
  foreach(var id in S["projects"].Keys){double stock=S["projects"][id].Get("inventory",V.Map()).Get(resource,0).Double,capacity=G.stock_cap_for(id,resource);var entries=m.Get("activity_ledger",V.Map()).Get(id,V.Arr()).Where(x=>x.Get("resource","").Text==resource).ToArray();if(stock<=0&&capacity<=0&&entries.Length==0)continue;double output=entries.Where(x=>x.Get("kind","").Text=="output").Sum(x=>x.Get("kept",x.Get("rate",0)).Double),resident=entries.Where(x=>x.Get("kind","").Text=="input"&&x.Get("category","").Text=="resident").Sum(x=>x.Get("rate",0).Double),construction=entries.Where(x=>x.Get("kind","").Text=="input"&&x.Get("category","").Text=="construction").Sum(x=>x.Get("rate",0).Double),input=entries.Where(x=>x.Get("kind","").Text=="input").Sum(x=>x.Get("rate",0).Double)-resident-construction;rows.Add(V.Map("id",id,"name",OperatingProjectIdentity(id),"a",output,"b",input,"c",resident,"d",construction,"net",output-input-resident-construction,"stock",stock,"capacity",capacity));}return rows;
 }
