  foreach(var item in rows){var row=item;var cells=new List<string>{row["name"].Text,CivicOMActual(row.Get("a",0).Double),CivicOMActual(row.Get("b",0).Double),CivicOMActual(row.Get("c",0).Double)};if(resource!="energy")cells.Add(CivicOMActual(row.Get("d",0).Double));cells.Add(OperatingSettled?Signed(row["net"].Double):"待首次结算");if(resource!="energy"&&resource!="currency")cells.Add(F(row["stock"].Double)+" / "+F(row["capacity"].Double));CivicOMRow(scroll,cells.ToArray(),selected:()=>CivicOMSelect(state,row["id"].Text),active:state.selection==row["id"].Text);}
