  }
  CivicOMTradeForm(inspector);if(WildDesign.Enabled(G))C.Fold(inspector,"希望城 · 技术贸易",CivicWildTrade);CivicEvidence(inspector,"完整运力周期记录",ledger);C.Button(actions,"资源与财政",()=>Navigate("resources",_tradeResource));
