  CivicOMToolbar(list,state,new[]{"all","current","alternative"},key=>V.Map("all","全部方案","current","现行政策","alternative","可替换方案")[key].Text,new[]{"value","name"},key=>key=="name"?"名称 ↑":"现行在前");var options=G.c.policies.Keys.Where(id=>G.c.policies[id]["slot"].Text==state.view).Where(id=>state.filter=="all"||state.filter=="current"&&id==currentId||state.filter=="alternative"&&id!=currentId).Where(id=>CivicOMSearch(state,G.c.policies[id]["name"].Text+" "+G.c.policies[id].Get("summary","").Text));var ids=(state.sort=="name"?options.OrderBy(id=>G.c.policies[id]["name"].Text):options.OrderBy(id=>id==currentId?0:1)).ToArray();CivicOMEnsure(state,ids);
  var weights=new[]{1.4f,3f,.8f,1f};CivicOMRow(list,new[]{"方案","规则与取舍","状态","实施即付"},true,weights:weights);var rows=CivicOMScroll(list,state).contentContainer;
  foreach(var item in ids){var id=item;var p=G.c.policies[id];CivicOMRow(rows,new[]{p["name"].Text,p.Get("summary","").Text,id==currentId?"现行":"候选",id==currentId?"—":F(price)+" 通货"},selected:()=>{if(_comparisonValid)ClearComparison();CivicOMSelect(state,id);},active:state.selection==id,weights:weights);}
