  if(ids.Length==0){C.Empty(rows,"此筛选下没有政策");return;}var selected=state.selection;var policy=G.c.policies[selected];var baseline=_planner.snapshot(G);var preview=_planner.policy(G,selected);var version=_planner.version(G);bool current=selected==currentId;
  C.Label(inspector,policy["name"].Text+(current?" · 现行":" · 候选"),"c-heading");C.Label(inspector,policy.Get("summary","").Text);C.Pair(inspector,"现行方案",G.c.policies.Get(currentId,V.Map()).Get("name","尚未采用").Text);
  if(preview.Get("ok",false).Bool){C.Label(inspector,"同一步下一结算预测","c-heading");C.Table(inspector,new[]{"指标","不更换","采用后","变化"},OperatingPolicyMetricRows(baseline,preview["map_snapshot"]).Select(x=>new[]{x["title"].Text,F(x["before"].Double),F(x["after"].Double),Signed(x["after"].Double-x["before"].Double)}));C.Button(inspector,"地图 · 不更换预测",()=>{_baseline=baseline;_proposal=V.Map();ShowForecastMap("baseline",baseline);});C.Button(inspector,"地图 · 采用后预测",()=>{_baseline=baseline;_proposal=preview;PublishComparison();ShowForecastMap("proposal",preview["map_snapshot"]);});}else C.Label(inspector,preview.Get("error","预测不可用").Text,"c-warning");
  C.Pair(inspector,"更换即付",current?"当前方案无更换费用":F(price)+" 通货");if(!current)C.Pair(inspector,"支付后余额",F(S.Get("currency",0).Double-price));C.Button(inspector,current?"当前已采用":"实施「"+policy["name"].Text+"」",()=>{if(version!=_planner.version(G)){RenderPage();ShowMessage("城市已变化，请核对刷新后的预测。");return;}Command(g=>g.switch_policy(selected));},true,!current&&preview.Get("ok",false).Bool&&S.Get("currency",0).Double>=price&&Runtime.ViewCanEditFocused);CivicEvidence(inspector,"候选完整规则",policy);if(currentId!="")CivicEvidence(inspector,"现行完整规则",G.c.policies[currentId]);
 }

 string CivicOMConstructionWait(V job,V capacity,double material)=>job["paused"].Bool?"已暂停":capacity["energy_ratio"].Double<=0?"等待电力":capacity["local_effective"].Double<=0?"等待施工能力":job["material"].Double>0&&material<=0?"等待材料":"共享能力与材料";
 void CivicOMConstruction(VisualElement body,VisualElement actions) {
  var state=CivicOMState("construction");var queue=Construction.queue(G);var capacity=Construction.capacity_breakdown(G);var crews=Construction.crews(G);var quote=Construction.crew_quote(G);double material=G.inventory_total("material");var summary=C.Row(body,"c-management-toolbar");C.Value(summary,"本区有效施工",F(capacity["local_effective"].Double),"CP / 来生月");C.Value(summary,"城市工程预留",F(capacity["city_effective"].Double),"CP / 来生月");C.Value(summary,"材料库存 / 队列尚需",F(material)+" / "+F(queue.Sum(x=>x["material"].Double)));C.Value(summary,"启用 / 全部项目",queue.Count(x=>!x["paused"].Bool)+" / "+queue.Count);CivicOMLayout(body,state,out var list,out var inspector);
  CivicOMToolbar(list,state,new[]{"all","active","paused","waiting"},key=>V.Map("all","全部工程","active","已启用","paused","已暂停","waiting","等待供给")[key].Text,new[]{"value","name","progress","material"},key=>V.Map("value","优先级 ↓","name","工程名称 ↑","progress","进度 ↓","material","尚需材料 ↓")[key].Text);
  var filtered=queue.Where(x=>state.filter=="all"||state.filter=="active"&&!x["paused"].Bool||state.filter=="paused"&&x["paused"].Bool||state.filter=="waiting"&&!x["paused"].Bool&&CivicOMConstructionWait(x,capacity,material)!="共享能力与材料").Where(x=>CivicOMSearch(state,ConstructionProjectIdentity(x)+" "+x["id"].Text));var jobs=(state.sort=="name"?filtered.OrderBy(ConstructionProjectIdentity):state.sort=="progress"?filtered.OrderByDescending(x=>x["total"].Double>0?1-x["work"].Double/x["total"].Double:0):state.sort=="material"?filtered.OrderByDescending(x=>x["material"].Double):filtered.OrderByDescending(x=>x["priority"].Double)).ToArray();CivicOMEnsure(state,jobs.Select(x=>x["id"].Text));
  CivicOMRow(list,new[]{"工程 / 地块","完工进度","剩余 CP","尚需材料","优先级","等待原因"},true);var rows=CivicOMScroll(list,state).contentContainer;
  foreach(var item in jobs){var job=item;var id=job["id"].Text;var row=CivicOMRow(rows,new[]{ConstructionProjectIdentity(job),F(job["total"].Double>0?(1-job["work"].Double/job["total"].Double)*100:0)+"%",F(job["work"].Double),F(job["material"].Double),job["priority"].Long>0?"优先":job["priority"].Long<0?"延后":"普通",CivicOMConstructionWait(job,capacity,material)},selected:()=>CivicOMSelect(state,id),active:state.selection==id);row.tooltip=ConstructionProjectDirection(job);}
  if(jobs.Length==0)C.Empty(rows,queue.Count==0?"暂无施工项目":"此筛选下暂无工程","从地图选择地块新建，或选择建筑升级。");else {var job=jobs.First(x=>x["id"].Text==state.selection);var id=job["id"].Text;C.Label(inspector,ConstructionProjectIdentity(job),"c-heading");C.Label(inspector,ConstructionProjectDirection(job),"c-small c-muted");C.Meter(inspector,"施工进度",job["total"].Double-job["work"].Double,job["total"].Double,"CP");C.Pair(inspector,"等待原因",CivicOMConstructionWait(job,capacity,material));C.Pair(inspector,"尚需材料",F(job["material"].Double));C.Label(inspector,"共享施工与材料按实际队列分配；库存不是本项目的预留。","c-small c-muted");var priorities=C.Row(inspector,"c-wrap");foreach(var priorityValue in new[]{1,0,-1}){var priority=priorityValue;var button=C.Button(priorities,priority>0?"优先":priority<0?"延后":"普通",()=>Command(g=>Construction.set_priority(g,id,priority)),enabled:Runtime.ViewCanEditFocused);button.EnableInClassList("is-selected",job["priority"].Long==priority);}C.Button(inspector,job["paused"].Bool?"继续施工":"暂停施工",()=>Command(g=>g.set_paused(id,!job["paused"].Bool)),enabled:Runtime.ViewCanEditFocused);CivicOMLocate(inspector,id);CivicEvidence(inspector,"本工程完整来源",job);}
  C.Label(inspector,"施工能力与临时队","c-heading");C.Pair(inspector,"常设方案效率","×"+F(capacity["multiplier"].Double,2));CivicKnownMeter(inspector,"供电满足",capacity["energy_ratio"].Double*100,100,"%","",OperatingSettled);foreach(var crew in crews)C.Pair(inspector,crew["id"].Text,"+"+F(crew["nominal_cp_per_month"].Double)+" CP/月 · "+CrewRemaining(crew));if(crews.Count==0)C.Label(inspector,"暂无临时施工队","c-small c-muted");C.Button(inspector,"招募施工队 · "+F(quote["cost"].Double,0)+" 通货",ConfirmHireConstructionCrew,true,quote["affordable"].Bool&&Runtime.ViewCanEditFocused);C.Label(inspector,"一次付费，不自动续费。空队列仍计时，暂停和离线不计时；临时队仅用于本区。","c-small c-muted");CivicEvidence(inspector,"施工能力完整来源",capacity);CivicEvidence(inspector,"最近实际施工周期",S["block"].Get("construction_last",V.Map()));CivicEvidence(inspector,"全部施工队来源",crews);CivicEvidence(inspector,"当前招募报价",quote);C.Button(actions,"材料收支",()=>Navigate("resources","material"));
 }
